-- Give every petty-cash batch a stable, human-readable number generated by
-- the database. Users should not have to invent or remember this identifier.
BEGIN;

CREATE SEQUENCE IF NOT EXISTS public.petty_cash_number_seq;

ALTER TABLE public.petty_cash_batches
  ADD COLUMN IF NOT EXISTS petty_cash_number text;

ALTER TABLE public.petty_cash_batches
  ALTER COLUMN petty_cash_number SET DEFAULT (
    'PC-' || to_char(current_date, 'YYYY') || '-' || lpad(nextval('public.petty_cash_number_seq')::text, 6, '0')
  );

UPDATE public.petty_cash_batches
SET petty_cash_number = 'PC-' || to_char(COALESCE(funding_date, current_date), 'YYYY') || '-' || lpad(nextval('public.petty_cash_number_seq')::text, 6, '0')
WHERE petty_cash_number IS NULL;

ALTER TABLE public.petty_cash_batches
  ALTER COLUMN petty_cash_number SET NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS petty_cash_batches_number_key
  ON public.petty_cash_batches(petty_cash_number);

COMMIT;
